name: Windows workspace archive

on:
  workflow_call:
    inputs:
      diagnostic_timing:
        type: boolean
        default: false

permissions:
  contents: read

env:
  CARGO_TERM_COLOR: never
  # Both producer and consumers keep the same ordinary Cargo profile inputs.
  CARGO_PROFILE_DEV_DEBUG: line-tables-only
  CARGO_PROFILE_TEST_DEBUG: line-tables-only
  RUST_TEST_THREADS: '1'
  MESH_TALK_TEST_TIMING: ${{ inputs.diagnostic_timing && '1' || '0' }}

jobs:
  build:
    name: Windows workspace build
    runs-on: windows-latest
    timeout-minutes: 60
    outputs:
      rust: ${{ steps.compiler.outputs.rust }}
    defaults:
      run:
        shell: bash
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          ref: ${{ github.sha }}
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: frontend/package-lock.json
      - name: Validate Windows native build dependencies
        run: node scripts/ci/windows-native-deps.mjs
      - uses: dtolnay/rust-toolchain@stable
        with:
          components: clippy, rustfmt, llvm-tools-preview
      - name: Pin producer compiler for consumers
        id: compiler
        run: rustc --version | awk '{print "rust=" $2}' >> "$GITHUB_OUTPUT"
      - uses: Swatinem/rust-cache@v2
        env:
          CARGO_TERM_COLOR: always
          RUST_TEST_THREADS: ''
        with:
          save-if: ${{ github.ref == 'refs/heads/main' }}
          workspaces: . -> target
          shared-key: workspace-checks-checks
          cache-on-failure: true
      - name: Frontend dependencies and structural checks
        run: |
          npm ci --prefix frontend
          node scripts/validation/standards.mjs
          node scripts/check-repository-hygiene.mjs
      - uses: taiki-e/install-action@v2.87.31
        with:
          tool: cargo-nextest@0.9.150,cargo-llvm-cov@0.8.7
      - name: Validate archive and coverage contracts
        # Native environment probes and real Cargo fixtures belong to this
        # serial owner, outside the parallel portable diagnostic suite.
        run: node --test --test-concurrency=1 scripts/ci/windows-native-deps.test.mjs scripts/ci/backend-coverage.test.mjs scripts/ci/rust-profile.test.mjs scripts/ci/windows-coverage-cli.test.mjs scripts/diagnostics/windows-coverage.test.mjs
      - name: Build frontend
        working-directory: frontend
        run: |
          npm run build
          npm run check:build-syntax
      - name: Clippy
        run: cargo clippy --workspace --all-targets -- -D warnings
      - name: Build production workspace
        run: cargo build --workspace --locked
      - name: Workspace doctests
        run: cargo test --workspace --doc --locked
      - name: Build one instrumented workspace archive
        env:
          MESH_WINDOWS_CRITICAL_RECOVERY_PROBE: '1'
        run: |
          eval "$(cargo llvm-cov show-env --sh)"
          node scripts/ci/windows-coverage.mjs produce "$RUNNER_TEMP/windows-workspace-archive"
      - name: Preserve early critical recovery diagnostic
        if: always()
        uses: actions/upload-artifact@v7
        with:
          name: windows-critical-recovery-probe-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/windows-critical-recovery-probe/
          if-no-files-found: ignore
          retention-days: 14
      - name: Upload sealed workspace archive
        uses: actions/upload-artifact@v7
        with:
          name: windows-workspace-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/windows-workspace-archive/
          compression-level: 0
          if-no-files-found: error
          retention-days: 3

  tests:
    name: Windows workspace tests (${{ matrix.shard }}/4)
    needs: build
    runs-on: windows-latest
    timeout-minutes: 90
    strategy:
      fail-fast: false
      matrix:
        shard: [1, 2, 3, 4]
    defaults:
      run:
        shell: bash
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          ref: ${{ github.sha }}
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1
        with:
          node-version: 22
      - uses: dtolnay/rust-toolchain@stable
        with:
          toolchain: ${{ needs.build.outputs.rust }}
          components: llvm-tools-preview
      - uses: taiki-e/install-action@v2.87.31
        with:
          tool: cargo-nextest@0.9.150,cargo-llvm-cov@0.8.7
      # No Cargo cache, dependency fetch, frontend rebuild or test compilation.
      - uses: actions/download-artifact@v8
        with:
          name: windows-workspace-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/windows-workspace-archive
      - name: Run validated serial shard and export partial coverage
        env:
          CARGO_NET_OFFLINE: 'true'
          # Collect every selected case so one failure does not hide later defects.
          MESH_WINDOWS_FAIL_FAST: '0'
        run: |
          eval "$(cargo llvm-cov show-env --sh)"
          node scripts/ci/windows-coverage.mjs consume "${{ matrix.shard }}" "$RUNNER_TEMP/windows-workspace-archive" "$RUNNER_TEMP/windows-workspace-results"
      - name: Preserve inventory, execution receipt and coverage
        if: always()
        uses: actions/upload-artifact@v7
        with:
          name: windows-workspace-results-${{ matrix.shard }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/windows-workspace-results/
          if-no-files-found: error
          retention-days: 14
      - name: Upload validated partial coverage to Codecov
        if: >-
          !(github.event_name == 'pull_request' &&
            github.base_ref == 'dev' &&
            github.event.pull_request.user.login == 'dependabot[bot]')
        uses: codecov/codecov-action@303a32d7a59b442fa8d48b6a1cc6825c09c847a5
  for (const binary of Object.values(binaries["rust-binaries"])) {
    const expected = normalize(path.join(target, "debug", binary.kind === "example" ? "examples" : "deps"));
    assert.ok(path.isAbsolute(binary["binary-path"]) && normalize(path.dirname(binary["binary-path"])) === expected, "Unsupported build layout/profile (upstream cargo-llvm-cov #520); expected v1 target/debug/deps or example target/debug/examples");
  }
}

export const criticalRecoveryProbeCases = Object.freeze([
  "node::group_chain_tests::background_group_gossip_reaches_end_of_chain_without_sender_or_roster_changes",
  "node::channels::account_self_control::tests::reference_modern_leave_request_overtakes_the_executors_held_requester_read",
  "node::channels::account_self_control::tests::reference_modern_leave_keeps_left_over_old_member_head_and_reopen",
  "node::forwarding::tests::forwarding_to_group_delivers_ordered_text_and_independent_merged_file",
  "node::node::tests::group_reception_failed_rollback_retries_without_new_traffic",
  "postoffice::maintenance::tests::actual_role_gc_supplies_free_pages_for_physical_progress",
  "node::account_documents::tests::custody_channel_setup_waits_for_post_create_authenticated_inventory",
  "node::account_documents::tests::custody_channel_setup_waits_for_same_lane_dm_recall_baseline",
  "node::account_documents::tests::custody_channel_setup_does_not_wait_for_independent_directory",
  "node::node::tests::accept_loop_compacts_received_profiles_without_desktop_runtime",
  "node::account_group::tests::message_action_reference::reference_member_reacts_over_noise_with_private_projection_and_history_off",
  "node::delivery_runtime_tests::account_file_own_copy_first_stays_canonical_and_never_confirms_target",
  "node::account_documents::tests::channel_custody_never_counts_sender_sibling_as_other_member",
  "node::account_sync::selection_tests::account_history_worker_reaches_original_archive_while_source_keeps_appending",
  "node::account_documents::tests::channel_custody_refreshes_holder_certificates_and_deduplicates_explicit_legacy_members",
]);
export function criticalRecoveryProbeEnabled(env = process.env) {
  const value = env.MESH_WINDOWS_CRITICAL_RECOVERY_PROBE;
  assert.ok(
    value === undefined || value === "0" || value === "1",
    "MESH_WINDOWS_CRITICAL_RECOVERY_PROBE must be 0 or 1",
  );
  return value === "1";
}

// Diagnostic only: no consumer receipt or LCOV output. The full four-shard
// acceptance remains mandatory even after this same-binary probe passes.
export async function runCriticalRecoveryProbe(
  { full, reuse, identity: sourceIdentity, archiveSha256, env = process.env },
  run = command,
) {
  if (!criticalRecoveryProbeEnabled(env)) return;
  const expectedNames = criticalRecoveryProbeCases.map(
    (name) => `mesh-talk-core::mesh_talk_core$${name}`,
  );
  const matches = full.filter((row) => expectedNames.includes(row.eventName));
  assert.equal(
    matches.length,
    expectedNames.length,
    `Critical recovery probe requires all ${expectedNames.length} archived cases`,
  );
  for (const name of expectedNames) {
    assert.equal(
      matches.filter((row) => row.eventName === name).length,
      1,
      "Critical recovery probe requires one of each exact case",
    );
  }
  assert.ok(
    matches.every((row) => row.selected && !row.ignored),
    "Critical recovery probe cases must be runnable",
  );
  assert.ok(
    path.isAbsolute(env.RUNNER_TEMP ?? ""),
    "Critical recovery probe requires absolute runner temp",
  );
  assert.match(
    archiveSha256 ?? "",
    /^[a-f0-9]{64}$/u,
    "Critical recovery probe requires sealed archive digest",
  );
  const relative = path.relative(
    realpathSync(process.cwd()),
    realpathSync(env.RUNNER_TEMP),
  );
  assert.ok(
    relative === ".." ||
      relative.startsWith(`..${path.sep}`) ||
      path.isAbsolute(relative),
    "Critical recovery profiles must remain outside the workspace/cache",
  );
  const directory = path.join(
    env.RUNNER_TEMP,
    "windows-critical-recovery-probe",
  );
  assert.ok(
    !existsSync(directory),
    "Critical recovery probe output already exists",
